-- Populate wiki article: ALE-DSGN-013-02 Furniture and Equipment Clearances
-- Updates article content, sources, and EI prompt.

-- Ensure wiki_article_sources table exists (may not be in schema file yet)
CREATE TABLE IF NOT EXISTS public.wiki_article_sources (
  source_id   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  article_id  UUID NOT NULL REFERENCES public.wiki_articles(article_id) ON DELETE CASCADE,
  label       TEXT NOT NULL,
  description TEXT,
  url         TEXT,
  source_type TEXT NOT NULL DEFAULT 'reference_standard',
  sort_order  SMALLINT NOT NULL DEFAULT 0,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

DO $$
DECLARE
  v_article_id uuid;
BEGIN

  UPDATE public.wiki_articles SET
    title            = 'Furniture and Equipment Clearances',
    subject_label    = 'ALE-DSGN-013 · Anthropometrics & Human Dimensions',
    difficulty_label = 'Foundational',
    ale_tests_you    = 'Compute room areas from furniture footprints plus clearances, verify if a given furniture arrangement fits within a room, calculate workstation areas for office planning, and apply PD 1096 minimum room standards.',
    updated_note     = 'Updated March 21, 2026',
    status           = 'published',
    content          = E'Furniture does not define a room. The space a person needs to use that furniture does.\n\nEvery dimension in architectural practice begins with the human body — reaching, sitting, passing, opening, turning. When you place a bed in a room you are not placing 1,900 mm of mattress. You are placing the mattress plus the zone a person needs to get into it, plus the zone to open a nightstand drawer, plus the passage to reach the other side.\n\nThe ALE tests this constantly. Questions give you a room size and ask whether a furniture arrangement fits. They give you a furniture arrangement and ask what minimum room size is required. The answer is always the same operation: footprints plus clearances plus circulation.\n\n<KeyValues items={[{value: "6.00", label: "sq m min bedroom"}, {value: "3.00", label: "sq m min kitchen"}, {value: "1.20", label: "sq m min toilet"}, {value: "900", label: "mm min passage"}]} />\n\n---\n\n## The governing principle\n\n<WikiCalloutBox type="most-tested">\n**Room area = furniture footprints + clearance zones + circulation.** A room is not just the furniture placed in it. It is the furniture, plus the space a person needs to use, access, and move around every piece. The ALE tests whether you account for all three.\n</WikiCalloutBox>\n\n<FormulaBlock label="Room Area Computation" steps={[{variable: "A_room", operator: "=", operands: ["Σ furniture", "Σ clearances", "circulation"], symbol: "+"}, {variable: "", operator: "", operands: ["furniture = bed + nightstand + wardrobe footprints"], comment: ""}, {variable: "", operator: "", operands: ["clearances = 900 mm beside bed, 600 mm in front of closet"], comment: ""}, {variable: "", operator: "", operands: ["circulation = passage width for movement through room"], comment: ""}]} />\n\n---\n\n## PD 1096 minimum room sizes\n\nThe 2004 Revised IRR of PD 1096 sets statutory minimums. These are floors, not targets.\n\n| Room type | Minimum area | Minimum dimension | Reference |\n|-----------|-------------|-------------------|-----------|\n| Habitable room (bedroom, living, dining) | `6.00 sq m` | `2.00 m` least dimension | §806 |\n| Kitchen | `3.00 sq m` | — | §806 |\n| Toilet and bath | `1.20 sq m` | — | §806 |\n| Maid\'s room | `4.50 sq m` | — | §806 |\n| Corridor / passage | `0.90 m` (900 mm) | — | §1207 |\n| Ceiling height (habitable) | — | `2.70 m` (ground floor) | §805 |\n| Ceiling height (upper floors) | — | `2.40 m` | §805 |\n\n<WikiCalloutBox type="ale-watch">\nPD 1096 §806 sets **two simultaneous conditions** for habitable rooms: area ≥ 6.00 sq m AND least dimension ≥ 2.00 m. A room that is 1.50 m × 5.00 m = 7.50 sq m fails the second condition. Both must be satisfied.\n</WikiCalloutBox>\n\n---\n\n## Bedroom: beds and clearances\n\n<BedSizeComparator />\n\nBed footprints are only the starting point. Every accessible side requires a clearance zone.\n\n| Clearance zone | Value | Reason |\n|---------------|-------|--------|\n| Beside bed (accessible side) | `900 mm` | Passage and dressing |\n| Foot of bed | `900 mm` | Circulation through room |\n| In front of wardrobe / closet | `600 mm` | Door swing + reach |\n| In front of dresser / bureau | `750 mm` | Seated or standing use |\n| Between twin beds | `900 mm` | Passage between |\n\n<BedroomPlanView />\n\n---\n\n## Dining: tables and seating clearances\n\nDining clearances vary by zone. The zone behind a seated diner (passage zone) is larger than the zone where no one passes.\n\n| Clearance zone | Value | Notes |\n|---------------|-------|-------|\n| Chair pushback only (no passage) | `600 mm` | Minimum to pull chair out |\n| Passage behind seated diner | `900 mm` | Movement while others are seated |\n| Primary traffic lane (with chairs) | `1,050 mm` | Comfortable passage + chair |\n| Table to wall (no chairs on wall side) | `450 mm` | Serving access |\n\n| Table size (rectangular) | Seats | Footprint |\n|-------------------------|-------|----------|\n| 750 × 1,500 mm | 6 | Standard family |\n| 900 × 2,400 mm | 8 | Formal dining |\n| 900 × 1,800 mm | 6–8 | Medium formal |\n| 750 × 900 mm | 4 | Small dining or breakfast |\n\n---\n\n## Kitchen: the work triangle\n\nThe work triangle connects the three primary work centers: refrigerator, sink, and range/cooktop. Efficient kitchen layouts minimize unnecessary movement within this triangle.\n\n| Work triangle rule | Value |\n|-------------------|-------|\n| Minimum leg length | `1,200 mm` |\n| Maximum leg length | `2,700 mm` |\n| Maximum total perimeter | `7,900 mm` |\n| Minimum clear aisle (one-cook) | `1,050 mm` |\n| Minimum clear aisle (two-cook) | `1,200 mm` |\n| Counter depth (standard) | `600 mm` |\n| Counter height (standard) | `850–900 mm` |\n\n<Tip title="Design Principle">\nIn Philippine residential practice, the most common kitchen layouts are the **L-shape** and **galley (corridor)**. The work triangle is most efficient when no single leg exceeds 2,700 mm and no leg is shorter than 1,200 mm. No element of the kitchen (island, table, or other obstruction) should intersect the triangle path.\n</Tip>\n\n---\n\n## Office: workstation areas\n\nOffice planning uses workstation area as the basic unit of space allocation. The ALE tests minimum areas for different workstation types and the total office area required for a given headcount.\n\n| Workstation type | Minimum area per person | Notes |\n|-----------------|------------------------|-------|\n| Open-plan workstation | `4.50 sq m` | Desk + chair + circulation share |\n| Semi-enclosed workstation | `6.00 sq m` | Partitioned, with lateral files |\n| Private office (junior) | `9.00 sq m` | Single occupant with visitor chair |\n| Private office (senior) | `12.00–16.00 sq m` | Conference capability |\n| Executive office | `20.00–25.00 sq m` | Reception area, separate seating |\n\n<FormulaBlock label="Office Area Calculation" steps={[{variable: "A_office", operator: "=", operands: ["n_workstations", "A_per_workstation", "shared_factor"], symbol: "×"}, {variable: "", operator: "", operands: ["shared_factor = 1.25 to 1.40 for corridors, reception, utilities"], comment: ""}, {variable: "", operator: "", operands: ["total net area × 1.30 = gross area (includes walls, columns, risers)"], comment: ""}]} />\n\n---\n\n## Living room seating and corridor widths\n\n<Tabs>\n<Tab label="Seating Clearances" value="seating">\n\n| Element | Value |\n|---------|-------|\n| Sofa to coffee table | `400–450 mm` |\n| Coffee table to opposing seat | `350–450 mm` |\n| Between two facing sofas | `1,000–1,200 mm` |\n| Sofa to TV wall | `2,400–3,600 mm` (screen-dependent) |\n| Circulation path through living room | `900 mm` minimum |\n| Comfortable conversation distance | `1,500–3,600 mm` |\n\n</Tab>\n<Tab label="Corridor Widths" value="corridors">\n\n| Context | Minimum width |\n|---------|---------------|\n| Residential passage (PD 1096) | `900 mm` |\n| Commercial corridor (single-loaded) | `1,200 mm` |\n| Commercial corridor (double-loaded) | `1,500 mm` |\n| Egress corridor (RA 9514) | `1,118 mm` (44 inches) |\n| Hospital corridor (patient transport) | `2,400 mm` |\n\n</Tab>\n<Tab label="BP 344 Accessible" value="bp344">\n\n| Element | Value |\n|---------|-------|\n| Accessible corridor (BP 344) | `1,500 mm` minimum |\n| Passing space (alcove) | `1,800 × 1,800 mm` |\n| Turning radius (wheelchair) | `1,500 mm` diameter |\n| Door clear width | `900 mm` |\n| Reach range (forward, unobstructed) | `380–1,220 mm` AFF |\n| Knee clearance (under counter) | `680 mm` high × `800 mm` deep |\n\n</Tab>\n</Tabs>\n\n---\n\n## Workstation area calculator\n\n<WorkstationCalculator />\n\n---\n\n## Common mistakes\n\n<WikiMistakeList mistakes={[{number: 1, title: "Forgot clearance zones", wrongValue: "Bed footprint only", correctValue: "Bed + 900 mm side clearances + 900 mm foot clearance", explanation: "Room area = furniture footprints PLUS all clearance zones PLUS circulation. Placing only the furniture footprint in the room produces a non-functional space."}, {number: 2, title: "Wrong PD 1096 bedroom minimum", wrongValue: "5.00 sq m", correctValue: "6.00 sq m with least dimension ≥ 2.00 m", explanation: "PD 1096 §806 sets two conditions simultaneously: area and minimum dimension. Both must be met. A narrow room can exceed 6.00 sq m and still fail."}, {number: 3, title: "Confusing passage zone with pushback zone in dining", wrongValue: "600 mm behind all seated diners", correctValue: "600 mm pushback-only; 900 mm where people walk behind", explanation: "The 600 mm clearance is for pulling out a chair only. Any zone where someone walks behind a seated diner needs 900 mm minimum."}, {number: 4, title: "Work triangle leg too long", wrongValue: "3,600 mm single leg", correctValue: "Maximum 2,700 mm per leg", explanation: "A leg exceeding 2,700 mm creates excessive travel within the kitchen. The maximum total perimeter is 7,900 mm. Each leg also has a 1,200 mm minimum."}, {number: 5, title: "Using old BP 344 corridor width", wrongValue: "1,200 mm", correctValue: "1,500 mm (2024 Revised IRR)", explanation: "The 2024 Revised IRR of BP 344 raised the accessible corridor minimum to 1,500 mm. Older review materials show 1,200 mm, which is superseded."}]} />\n\n---\n\n## Dimension memory drill\n\n<DimensionDrill />\n\n---\n\n## Check yourself\n\n<InlineQuiz question="A bedroom is 2.50 m × 2.60 m. Does it meet PD 1096 §806 for a habitable room?" options={[{text: "Yes — area is 6.50 sq m and both dimensions exceed 2.00 m", is_correct: true}, {text: "No — the area is below 6.00 sq m", is_correct: false}, {text: "No — the minimum dimension must be 2.50 m", is_correct: false}, {text: "Yes — any room above 5.00 sq m qualifies", is_correct: false}]} rationale="Area = 2.50 × 2.60 = 6.50 sq m ≥ 6.00 ✓. Least dimension = 2.50 m ≥ 2.00 m ✓. Both conditions of PD 1096 §806 are met." />\n\n<InlineQuiz question="A dining room is 3.0 m wide. A table is 900 mm wide and centered. A person is seated on each long side. What is the clearance on each long side?" options={[{text: "1,050 mm — adequate for passage behind a seated diner", is_correct: true}, {text: "600 mm — adequate for chair pushback only", is_correct: false}, {text: "2,100 mm — the full remaining width with no division", is_correct: false}, {text: "450 mm — the table centerline offset", is_correct: false}]} rationale="Remaining width = 3,000 − 900 = 2,100 mm. Divided equally on two sides = 1,050 mm each. This exceeds the 900 mm minimum for passage behind a seated diner." />\n\n<InlineQuiz question="What is the minimum area for an open-plan office workstation per person?" options={[{text: "3.00 sq m", is_correct: false}, {text: "4.50 sq m", is_correct: true}, {text: "6.00 sq m", is_correct: false}, {text: "9.00 sq m", is_correct: false}]} rationale="The ALE standard for an open-plan workstation is 4.50 sq m per person. This accounts for the desk footprint, chair clearance, and the proportional share of circulation space in an open floor plate." />\n'
  WHERE slug = 'ale-dsgn-013-02'
  RETURNING article_id INTO v_article_id;

  IF v_article_id IS NULL THEN
    RAISE EXCEPTION 'No wiki_articles row found with slug = ale-dsgn-013-02';
  END IF;

  -- ── Sources ──────────────────────────────────────────────────
  DELETE FROM public.wiki_article_sources WHERE article_id = v_article_id;

  INSERT INTO public.wiki_article_sources (article_id, label, description, url, source_type, sort_order) VALUES
    (v_article_id, 'Panero & Zelnik', 'Human Dimension & Interior Space (1979) — the foundational anthropometric reference for furniture and clearance dimensions', NULL, 'reference_standard', 1),
    (v_article_id, 'Ernst Neufert', 'Architects'' Data, 4th Edition — clearance dimensions for residential, office, and dining spaces', NULL, 'reference_standard', 2),
    (v_article_id, 'PD 1096 — 2004 Revised IRR', '§805 ceiling heights, §806 minimum room sizes, §1207 corridor and passage widths', NULL, 'implementing_rules', 3),
    (v_article_id, 'BP 344 — 2024 Revised IRR', 'Accessible clearances, turning radii, knee clearances, and corridor minimums', NULL, 'implementing_rules', 4),
    (v_article_id, 'ALE Standard Dimensions', 'Licensure Exam standard values for bed sizes, dining tables, and workstation areas as used in ALE design scenarios', NULL, 'prc_syllabus', 5);

  -- ── EI Prompt ─────────────────────────────────────────────────
  INSERT INTO public.wiki_ei_prompts (
    article_id,
    prompt_text,
    reveal_text,
    insert_after_heading,
    options,
    sort_order,
    is_active,
    status
  ) VALUES (
    v_article_id,
    'A rectangular dining room is 3.0 m × 4.0 m. A client wants a rectangular table for 8 people (900 × 2,400 mm) centered in the room. Is this possible with adequate clearances on all sides?',
    'Room width = 3,000 mm. Table width = 900 mm. Remaining = 2,100 mm ÷ 2 sides = 1,050 mm per long side (≥ 900 mm for passage behind seated diner ✓). Room length = 4,000 mm. Table length = 2,400 mm. Remaining = 1,600 mm ÷ 2 sides = 800 mm per short side (≥ 600 mm for chair pushback ✓). The room works — distinguish between pushback-only zones (600 mm) and passage zones (900 mm+).',
    'Dining: tables and seating clearances',
    '[
      {"text": "Yes — clearance is 1,050 mm on each long side and 800 mm on each short side", "is_correct": true},
      {"text": "No — the short-side clearance is only 300 mm, below the 600 mm minimum", "is_correct": false},
      {"text": "Yes — the ALE only checks long-side clearances", "is_correct": false},
      {"text": "No — the table is too large for an 8-person setting", "is_correct": false}
    ]'::jsonb,
    0,
    true,
    'published'
  );

END $$;

